extends "res://game/world/generation/office_generator.gd"
## 4d, tramo final: office_generator with its furniture pass watched, to tell
## why the toilets rooms lose a sure piece (office_test floor_recipes()). Each
## pass keeps what it laid against (`last`); simulate() then lays every toilets
## room of the last pass again on a bare copy with the same zones, once with
## the palette's recipe ("V0") and once with each of VARIANTS.
## The recipes tried, in the palette's form [kind, how, least, most, row].
const VARIANTS := {
    "V1": [["cubicles", "wall", 1, 1, 1], ["locker_bank", "wall", 1, 2, 1], ["bench_slat", "middle", 1, 1, 1], ["bin_floor", "spare", 1, 1, 1]],
    "V2": [["cubicles", "wall", 1, 1, 1], ["locker_bank", "wall", 1, 1, 1], ["bench_slat", "middle", 1, 1, 2], ["bin_floor", "spare", 1, 1, 1]],
    "V3": [["cubicles", "wall", 1, 1, 1], ["locker_bank", "wall", 1, 1, 1], ["bench_slat", "middle", 1, 1, 1], ["bin_floor", "spare", 1, 1, 1]],
    "V4": [["cubicles", "wall", 1, 1, 1], ["bench_slat", "middle", 1, 1, 2], ["locker_bank", "wall", 1, 2, 1], ["bin_floor", "spare", 1, 1, 1]],
    "V5": [["cubicles", "wall", 1, 1, 1], ["bench_slat", "middle", 1, 1, 1], ["locker_bank", "wall", 1, 2, 1], ["bin_floor", "spare", 1, 1, 1]],
}
## office_test's sure pieces of the toilets.
const SURE := ["cubicles", "locker_bank", "bench_slat"]
## A locker's spot in job.taken (office_generator.candidate() registers it so).
const LOCKER_HALF := 0.65

var last := {}

func furnish_furniture(job: Dictionary) -> String:
    var reason: String = super.furnish_furniture(job)
    var view := working(job)
    view["spots"] = LAYOUT.fixtures_by_room(view)
    var have := {}
    var basins := {}
    var wanting := 0
    var lacking := 0
    for room in job.f.rooms:
        var wanted: int = palette.WARDROBES.get(int(room.type), 0)
        if wanted > 0 and int(room.hall) < 0:
            wanting += 1
            var hides: Array = room.get("hides", [])
            if hides.size() < wanted: lacking += 1
        if int(room.type) != palette.TOILETS or bool(room.corridor): continue
        var kinds := {}
        for it in room.furniture: kinds[String(it.kind)] = true
        have[int(room.id)] = SURE.all(func(k): return kinds.has(k))
        var props: Array = room.get("props", [])
        basins[int(room.id)] = props.any(func(p): return String(p.kind) == "basin")
    last = {"view": view, "taken": job.taken.duplicate(true), "have": have, "basins": basins, "wanting": wanting, "lacking": lacking, "seed": int(job.seed), "attempt": int(job.attempt)}
    return reason

## Each toilets room of the last pass: its span, whether the real pass gave it
## the sure pieces and a basin, whether each recipe would ("V0", the palette's,
## and VARIANTS), and, for each sure piece the palette's recipe leaves out,
## whether it fits laid alone, and laid alone with no lockers in the room.
func simulate() -> Array:
    var out: Array = []
    if last.is_empty(): return out
    var view: Dictionary = last.view
    var have: Dictionary = last.have
    var basins: Dictionary = last.basins
    var spots: Dictionary = last.taken
    var today: Array = palette.ROOM_FURNITURE[palette.TOILETS]
    var run_seed := int(last.seed)
    var attempt := int(last.attempt)
    for id in have:
        var room: Dictionary = view.rooms[int(id)]
        var taken: Array = spots.get(int(id), [])
        var kinds := lay_copy(view, room, taken, today, run_seed, attempt, true)
        var laid := {"V0": SURE.all(func(k): return kinds.has(k))}
        for key in VARIANTS:
            var tried := lay_copy(view, room, taken, VARIANTS[key], run_seed, attempt, true)
            laid[key] = SURE.all(func(k): return tried.has(k))
        var miss := {}
        for kind in SURE:
            if kinds.has(kind): continue
            var line: Array = today.filter(func(entry): return String(entry[0]) == kind)
            var alone := lay_copy(view, room, taken, line, run_seed, attempt, true).has(kind)
            var unlocked := lay_copy(view, room, taken, line, run_seed, attempt, false).has(kind)
            miss[kind] = [alone, unlocked]
        var low := minf(float(room.span_x), float(room.span_z))
        var high := maxf(float(room.span_x), float(room.span_z))
        out.append({"span": "%.1fx%.1f" % [low, high], "real": bool(have[id]), "basin": bool(basins[id]), "laid": laid, "miss": miss})
    return out

## The kinds laid when `recipe` goes into a bare copy of `room` with the zones
## furnish_furniture() gives it; with `lockers` false, as if the room had none
## (no hides, no locker spots taken).
func lay_copy(view: Dictionary, room: Dictionary, taken: Array, recipe: Array, run_seed: int, attempt: int, lockers: bool) -> Dictionary:
    var copy: Dictionary = room.duplicate(true)
    copy["furniture"] = []
    copy["props"] = []
    var spots: Array = taken
    if not lockers:
        copy["hides"] = []
        spots = taken.filter(func(spot): return not is_equal_approx(float(spot.half), LOCKER_HALF))
    copy["feature"] = RECIPES.feature_of(view, copy)
    var zones := RECIPES.keep_clear(view, copy, spots)
    var walk: Array = zones + RECIPES.ways_in(copy, spots)
    var rng := RandomNumberGenerator.new()
    rng.seed = hash([run_seed, attempt, int(room.id)])
    var chain := {}
    for entry in recipe: RECIPES.lay(copy, walk, entry, rng, chain)
    var kinds := {}
    for it in copy.furniture: kinds[String(it.kind)] = true
    return kinds

