extends SceneTree
## 4d, tramo final: why the toilets rooms lose a sure piece of their recipe
## (office_test, "Cada tipo con receta y 4 salas o más..."), over office_test's
## 64 runs, and how many would keep all three under each of
## 4d_aseos_gen.VARIANTS. ASEOS_ELIGE names the first of ORDER that gives them
## to PICK_SHARE % of the rooms or more, once the bare copy of the palette's
## recipe comes within CAL_SHARE % of the rooms of the real pass.
const GEN := preload("res://evidence/4d_aseos_gen.gd")
const OFFICE := preload("res://game/floors/palettes/office_palette.gd")
const ORDER := ["V1", "V4", "V5", "V2", "V3"]
const PICK_SHARE := 55
const CAL_SHARE := 5

func _initialize() -> void:
    var runs: Array = []
    for run_seed in range(1, 41): runs.append([run_seed, 2])
    for run_seed in range(41, 47):
        for survivors in [1, 3, 4, 5]: runs.append([run_seed, survivors])
    var rooms := 0
    var real := 0
    var fallen := 0
    var basins := 0
    var wanting := 0
    var lacking := 0
    var whole := {}
    var miss := {}
    var spans := {}
    for run in runs:
        var generator = GEN.new()
        var manifest: Dictionary = generator.generate(int(run[0]), int(run[1]))
        if manifest.is_empty() or bool(manifest.get("fallback", false)):
            fallen += 1
            continue
        var watched: Dictionary = generator.last
        wanting += int(watched.get("wanting", 0))
        lacking += int(watched.get("lacking", 0))
        for entry: Dictionary in generator.simulate():
            rooms += 1
            var laid: Dictionary = entry.laid
            if bool(entry.real): real += 1
            if bool(entry.basin): basins += 1
            for key in laid:
                if bool(laid[key]): whole[key] = int(whole.get(key, 0)) + 1
            var span := String(entry.span)
            if not spans.has(span): spans[span] = [0, 0, 0]
            var row: Array = spans[span]
            row[0] = int(row[0]) + 1
            if bool(entry.real): row[1] = int(row[1]) + 1
            if bool(laid.V0): row[2] = int(row[2]) + 1
            var lost: Dictionary = entry.miss
            for kind in lost:
                if not miss.has(kind): miss[kind] = [0, 0, 0]
                var count: Array = miss[kind]
                var why: Array = lost[kind]
                count[0] = int(count[0]) + 1
                if bool(why[0]): count[1] = int(count[1]) + 1
                if bool(why[1]): count[2] = int(count[2]) + 1
    var sim := int(whole.get("V0", 0))
    print("ASEOS_RUNS runs=%d fallen=%d rooms=%d recipe=%s" % [runs.size(), fallen, rooms, str(OFFICE.ROOM_FURNITURE[OFFICE.TOILETS])])
    print("ASEOS_CAL real_whole=%d sim_whole=%d" % [real, sim])
    for kind in GEN.SURE:
        var count: Array = miss.get(kind, [0, 0, 0])
        print("ASEOS_MISS kind=%s rooms=%d alone=%d alone_without_lockers=%d" % [kind, int(count[0]), int(count[1]), int(count[2])])
    var keys: Array = spans.keys()
    keys.sort()
    for span in keys:
        var row: Array = spans[span]
        print("ASEOS_SPAN span=%s rooms=%d real_whole=%d sim_whole=%d" % [span, int(row[0]), int(row[1]), int(row[2])])
    for key in GEN.VARIANTS:
        print("ASEOS_VAR name=%s whole=%d rooms=%d recipe=%s" % [key, int(whole.get(key, 0)), rooms, str(GEN.VARIANTS[key])])
    print("ASEOS_BASIN rooms=%d with_basin=%d" % [rooms, basins])
    print("ASEOS_HIDES lacking=%d of=%d" % [lacking, wanting])
    var pick := "NINGUNA"
    if rooms == 0 or absi(sim - real) * 100 > rooms * CAL_SHARE:
        pick = "CALIBRACION"
    else:
        for key in ORDER:
            if int(whole.get(key, 0)) * 100 >= rooms * PICK_SHARE:
                pick = String(key)
                break
    print("ASEOS_ELIGE %s" % pick)
    print("ASEOS_PROBE done")
    quit(0)

